<script>
(()=>{const form=document.querySelector('[data-delivery-page-form]'),canvas=form?.querySelector('[data-delivery-page-canvas]'),box=canvas?.closest('.delivery-signature'),hidden=form?.elements.assinatura_recebedor,name=form?.elements.recebedor_nome,submit=form?.querySelector('[type=submit]');if(!form||!canvas||!box||!hidden||!name||!submit)return;const ctx=canvas.getContext('2d');let drawing=false,ink=false;const resize=()=>{const old=hidden.value,rect=canvas.getBoundingClientRect(),ratio=devicePixelRatio||1;if(rect.width<2||rect.height<2)return;canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);ctx.setTransform(ratio,0,0,ratio,0,0);ctx.strokeStyle='#111827';ctx.lineWidth=2.2;ctx.lineCap='round';ctx.lineJoin='round';if(old){const image=new Image();image.onload=()=>{ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.drawImage(image,0,0,canvas.width,canvas.height);ctx.restore();ctx.setTransform(ratio,0,0,ratio,0,0)};image.src=old}};const update=()=>{submit.disabled=false};const save=()=>{if(ink)hidden.value=canvas.toDataURL('image/png');update()};const clear=()=>{ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);ctx.restore();hidden.value='';drawing=false;ink=false;box.classList.remove('has-ink');update()};const point=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};requestAnimationFrame(()=>requestAnimationFrame(resize));name.addEventListener('input',update);canvas.addEventListener('pointerdown',e=>{e.preventDefault();drawing=true;ink=true;box.classList.add('has-ink');const p=point(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.1,p.y+.1);ctx.stroke();try{canvas.setPointerCapture(e.pointerId)}catch(error){}});canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke();save()});const finish=e=>{if(!drawing)return;drawing=false;save();try{canvas.releasePointerCapture(e.pointerId)}catch(error){}};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);window.addEventListener('pointerup',finish,true);form.querySelector('[data-delivery-page-clear]').addEventListener('click',clear);window.addEventListener('resize',()=>{if(!drawing)resize()});form.addEventListener('submit',e=>{if(!name.value.trim()||!hidden.value){e.preventDefault();const message=!name.value.trim()&&!hidden.value?'Informe o nome do recebedor e faça a assinatura.':(!name.value.trim()?'Informe o nome do recebedor.':'Faça a assinatura do recebedor.');if(window.showAppToast)window.showAppToast(message,'error');else window.alert(message)}});update()})();
(()=>{const form=document.querySelector('[data-delivery-page-form]'),canvas=form?.querySelector('[data-delivery-page-canvas]'),box=canvas?.closest('.delivery-signature'),done=box?.querySelector('[data-delivery-page-done]'),cancel=box?.querySelector('[data-delivery-page-cancel]');if(!form||!canvas||!box||!done||!cancel)return;const mobile=()=>window.matchMedia('(max-width:700px)').matches;const close=async()=>{if(document.fullscreenElement===box){try{await document.exitFullscreen()}catch(error){}}box.classList.remove('is-mobile-expanded');document.body.classList.remove('delivery-signature-open');try{screen.orientation?.unlock?.()}catch(error){}window.dispatchEvent(new Event('resize'))};canvas.addEventListener('pointerdown',async event=>{if(!mobile()||box.classList.contains('is-mobile-expanded'))return;event.preventDefault();event.stopImmediatePropagation();box.classList.add('is-mobile-expanded');document.body.classList.add('delivery-signature-open');try{await box.requestFullscreen?.({navigationUI:'hide'});await screen.orientation?.lock?.('landscape')}catch(error){}window.dispatchEvent(new Event('resize'))},true);cancel.addEventListener('click',close);done.addEventListener('click',async()=>{await close();form.requestSubmit()});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&box.classList.contains('is-mobile-expanded'))close()});window.addEventListener('keydown',event=>{if(event.key==='Escape'&&box.classList.contains('is-mobile-expanded'))close()})})();
</script>
